long long paths(int r, int c) {
    if (r == 1 || c == 1) {
        return 1;
    }
    if (memo[r][c] != 0) {
        return memo[r][c];
    }
    memo[r][c] = paths(r - 1, c) + paths(r, c - 1);
    return memo[r][c];
}

int main() {
    long long r;
    long long c;
    cin >> r >> c;

    cout << paths(r, c) << endl;

    return 0;
}

