import java.util.*;

public class Main {
    static long[][] memo = new long[20][20];

    static long paths(int r, int c) {
        if (r == 1 || c == 1) {
            return 1;
        }
        if (memo[r][c] != 0) {
            return memo[r][c];
        }
        memo[r][c] = paths(r - 1, c) + paths(r, c - 1);
        return memo[r][c];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long r = sc.nextLong();
        long c = sc.nextLong();

        System.out.println(paths((int) r, (int) c));
    }
}
